<script module lang="ts">
/**
 * A command list behind a trigger (`design/components/menu.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/menu.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, setContext, type Snippet } from 'svelte'

import * as zag from '@zag-js/menu'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  Portal,
  agentMember,
  anchorProps,
  attributes,
  chooseMenuEntry,
  followHighlight,
  joinSlot,
  menuChoices,
  mergeParts,
  normalizeProps,
  syncTriggerAnchor,
  useDirection,
  useMediaQuery,
  watchEffect,
  type IconRole,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/menu.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'
import Kbd from '../structure/Kbd.svelte'
import MenuSubmenu from './MenuSubmenu.svelte'

export type MenuPresentation = NonNullable<MenuProps['presentation']>

export type MenuAlign = NonNullable<MenuProps['align']>

export interface MenuItemEntry {
  kind?: 'item'
  label: string
  icon?: IconRole
  kbd?: string
  tone?: 'neutral' | 'danger'
  disabled?: boolean
  onSelect: () => void
}

export interface MenuCheckboxEntry {
  kind: 'checkbox'
  label: string
  checked: boolean
  onCheckedChange: (checked: boolean) => void
  disabled?: boolean
}

export interface MenuSeparatorEntry {
  kind: 'separator'
}

export interface MenuLabelEntry {
  kind: 'label'
  label: string
}

export type MenuLeafEntry = MenuItemEntry | MenuCheckboxEntry | MenuSeparatorEntry | MenuLabelEntry

export interface MenuSubmenuEntry {
  kind: 'submenu'
  label: string
  icon?: IconRole
  disabled?: boolean
  items: MenuLeafEntry[]
}

export type MenuEntry = MenuLeafEntry | MenuSubmenuEntry

export interface MenuProps {
  align?: 'start' | 'end'
  /**
   * Opens on mount, for galleries and tests; screens let the user open it.
   */
  defaultOpen?: boolean
  items: MenuEntry[]
  onOpenChange?: (open: boolean) => void
  /**
   * The controlled pair; uncontrolled is the default. Use it to keep the menu open across
   * several checkbox toggles, or to close it on "apply".
   */
  open?: boolean
  /**
   * `'auto'` uses a sheet below `30rem` (the sheet presentation, `design/components/README.md`),
   * the phone's standard pattern for "choose from these". `'popover'` keeps the popper at every
   * width, for the rare pointer-first embed that needs precision. There is no always-`'sheet'`
   * value, because a bottom sheet does not suit a wide pointer surface, and the closed union
   * rejects it (`docs/layout.md`).
   */
  presentation?: 'auto' | 'popover'
  /**
   * A governed control, usually a `Button` with `iconOnly icon="overflow"`.
   */
  trigger: Snippet
}
</script>

<script lang="ts">
let {
  align = 'start',
  defaultOpen,
  items,
  onOpenChange,
  open,
  presentation = 'auto',
  trigger,
}: MenuProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
let anchor = $state<HTMLElement | null>(null)
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
let sheetPanel = $state<HTMLElement | null>(null)
const phone = useMediaQuery('phone')
const sheeting = $derived(presentation === 'auto' && phone.current)
const flat = $derived(
  items.flatMap((entry) =>
    entry.kind === 'submenu'
      ? [{ kind: 'label' as const, label: entry.label }, ...(entry.disabled ? [] : entry.items)]
      : [entry],
  ),
)
const documentDirection = useDirection(() => anchor)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      open: open,
      defaultOpen: defaultOpen,
      positioning: { placement: `bottom-${align}`, gutter: 2 },
      onOpenChange: (details) => {
        onOpenChange?.(details.open)
      },
      onSelect: (details) => {
        flat.forEach(
          (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
        )
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const present = usePresence(
  () => api.open && !sheeting,
  () => panel,
)
const sheetPresent = usePresence(
  () => api.open && sheeting,
  () => sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(
  () => api.open && sheeting,
  () => scrim,
  'dialog.scrim',
)
setContext('polymorph:Menu', {
  get api() {
    return api
  },
  get service() {
    return service
  },
})
const effect1 = () => {
  syncTriggerAnchor(anchor, api.getTriggerProps(), api.open)
}
watchEffect(effect1, { watch: () => api.open })
const effect2 = () => {
  followHighlight(panel, api.highlightedValue)
}
watchEffect(effect2, { watch: () => api.highlightedValue })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'Menu',
    element: () => anchor?.querySelector('button, a[href], [tabindex]'),
    state: () => ({ open: api.open, entries: menuChoices(items) }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) => chooseMenuEntry(items, value) && api.open && api.setOpen(false),
      },
      open: () => api.open || api.setOpen(true),
      close: () => api.open && api.setOpen(false),
    },
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span
    bind:this={anchor}
    {...attributes(anchorProps(api.getTriggerProps()))}
    class={triggerAnchor.anchor}
    >{@render trigger?.()
  }</span
  ><Portal
    >{#if present.current
      }<div {...attributes(api.getPositionerProps())}
        ><div
          bind:this={panel}
          {...attributes(mergeParts(api.getContentProps(), { onFocus: () => { followHighlight(panel, api.highlightedValue) } }))}
          class={styles.content}
          style:--radix-dropdown-menu-content-available-height={'var(--available-height)'}
          style:--radix-dropdown-menu-content-transform-origin={'var(--transform-origin)'}
          hidden={undefined}
          data-member="menu"
          >{#each items as entry, index (index)
            }{#if entry.kind === 'separator'
              }<div {...attributes(api.getSeparatorProps())} class={styles.separator}></div
            >{:else if entry.kind === 'label'
              }<div class={styles.groupLabel}>{entry.label}</div
            >{:else if entry.kind === 'checkbox'
              }<div
                {...attributes(mergeParts(api.getOptionItemProps({ type: 'checkbox', value: entry.label, checked: entry.checked, disabled: entry.disabled, closeOnSelect: false, onCheckedChange: entry.onCheckedChange }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                class={[styles.item, styles.checkbox]}
                data-menu-part="checkbox"
                tabindex="-1"
                ><span class={styles.check}
                  >{#if entry.checked}<Icon name="confirm" size="sm" />{/if
                }</span
                ><span class={styles.label}>{entry.label}</span
              ></div
            >{:else if entry.kind === 'submenu'
              }<MenuSubmenu {entry}
            />{:else
              }<div
                {...attributes(mergeParts(api.getItemProps({ value: entry.label, disabled: entry.disabled }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                class={styles.item}
                data-tone={entry.tone ?? 'neutral'}
                tabindex="-1"
                >{#if entry.icon !== undefined
                  }<span class={styles.glyph}><Icon name={entry.icon} size="sm" /></span
                >{/if
                }<span class={styles.label}>{entry.label}</span
                >{#if entry.kbd !== undefined
                  }<span class={styles.hint}><Kbd>{entry.kbd}</Kbd></span
                >{/if
              }</div
            >{/if
          }{/each
        }</div
      ></div
    >{/if
    }{#if scrimPresent.current
      }<div bind:this={scrim} class={sheet.scrim} data-state={api.open ? 'open' : 'closed'}></div
    >{/if
    }{#if sheetPresent.current
      }<div class={sheet.positioner}
        ><div
          bind:this={sheetPanel}
          class={sheet.panel}
          data-presentation="sheet"
          data-state={api.open ? 'open' : 'closed'}
          tabindex="-1"
          ><div
            bind:this={panel}
            {...attributes(mergeParts(api.getContentProps(), { onFocus: () => { followHighlight(panel, api.highlightedValue) } }))}
            class={styles.sheetList}
            hidden={undefined}
            data-member="menu"
            >{#each flat as entry, index (index)
              }{#if entry.kind === 'separator'
                }<div {...attributes(api.getSeparatorProps())} class={styles.separator}></div
              >{:else if entry.kind === 'label'
                }<div class={styles.groupLabel}>{entry.label}</div
              >{:else if entry.kind === 'checkbox'
                }<div
                  {...attributes(mergeParts(api.getOptionItemProps({ type: 'checkbox', value: entry.label, checked: entry.checked, disabled: entry.disabled, closeOnSelect: false, onCheckedChange: entry.onCheckedChange }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                  class={[styles.item, styles.checkbox]}
                  data-menu-part="checkbox"
                  tabindex="-1"
                  ><span class={styles.check}
                    >{#if entry.checked}<Icon name="confirm" size="sm" />{/if
                  }</span
                  ><span class={styles.label}>{entry.label}</span
                ></div
              >{:else
                }<div
                  {...attributes(mergeParts(api.getItemProps({ value: entry.label, disabled: entry.disabled }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                  class={styles.item}
                  data-tone={entry.tone ?? 'neutral'}
                  tabindex="-1"
                  >{#if entry.icon !== undefined
                    }<span class={styles.glyph}><Icon name={entry.icon} size="sm" /></span
                  >{/if
                  }<span class={styles.label}>{entry.label}</span
                  >{#if entry.kbd !== undefined
                    }<span class={styles.hint}><Kbd>{entry.kbd}</Kbd></span
                  >{/if
                }</div
              >{/if
            }{/each
          }</div
        ></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
